import XCTest
@testable import ImeData

final class DictWriterTests: XCTestCase {
    func testRenderFormat() {
        let text = DictWriter.render(name: "t", sort: "original", sources: ["source A"], entries: [
            DictEntry(text: "日", code: "a", weight: nil), DictEntry(text: "中國", code: "zhong guo", weight: 5)])
        XCTAssertEqual(text, """
        # t.dict.yaml (Remote Keyboard)
        #
        # source A
        # Generated by scripts/rime/make-dicts.sh; do not edit by hand. See LICENSE-data.txt.
        ---
        name: t
        version: "2026.11.20"
        sort: original
        ...

        日\ta
        中國\tzhong guo\t5

        """)
    }
}

final class VersionsLockTests: XCTestCase {
    func testFindsUrlByName() {
        let lock = "# c\nlibrime 1.17.0 https://a/b.tar.gz abc\n\nlibcangjie-table 346 https://c/table.txt def\n"
        XCTAssertEqual(VersionsLock.url(named: "libcangjie-table", in: lock), "https://c/table.txt")
        XCTAssertNil(VersionsLock.url(named: "missing", in: lock))
    }
}
